"""Demo clients from test_data/ (fictional, generated by taxmind/synth_ca.py)."""
from __future__ import annotations

import json
import shutil

from sqlalchemy.orm import Session

from . import service as S
from .auth import hash_password
from .db import Client, Period, StoredFile, User, jdump
from .settings import FILES, TEST_DATA

PROFILES = {
    "a_manufacturer_plant": {"line_of_business": [], "policy": "reverse"},
    "b_trader": {"line_of_business": [], "policy": "reverse"},
    "c_hotel_restaurant": {"line_of_business": ["hotel", "caterer"], "policy": "reverse"},
    "d_works_contractor": {"line_of_business": ["works_contractor"], "policy": "reverse"},
    "e_car_dealer": {"line_of_business": ["vehicle_dealer"], "policy": "reverse"},
    "f_professional_multi_gstin": {"line_of_business": [], "policy": "pending"},
}
DEMO_USERS = [("riya", "Riya Sharma", "preparer"), ("aman", "Aman Gupta", "preparer"),
              ("camehta", "CA Mehta", "reviewer")]


def seed(db: Session, user: str, reconcile_n: int | None = None) -> int:
    if not TEST_DATA.exists():
        raise FileNotFoundError("test_data/ is missing - generate it with `python -m taxmind.synth_ca --out test_data`.")
    for un, name, role in DEMO_USERS:
        if not db.query(User).filter_by(username=un).first():
            db.add(User(username=un, name=name, role=role, password_hash=hash_password("demo123")))
    db.commit()
    made = 0
    for i, (folder, st) in enumerate(PROFILES.items()):
        d = TEST_DATA / folder
        if not (d / "truth.json").exists():
            continue
        meta = json.loads((d / "truth.json").read_text())["meta"]
        if db.query(Client).filter_by(gstin=meta["client_gstin"]).first():
            continue
        settings = dict(S.DEFAULT_SETTINGS)
        settings.update(st)
        c = Client(name=meta["client_name"], gstin=meta["client_gstin"], notes=meta.get("description", ""),
                   settings_json=jdump(settings))
        db.add(c)
        db.flush()
        F = meta["files"]
        vm = d / F["vendor_master"]
        if vm.exists():
            dest = FILES / str(c.id) / "vendor_master" / "demo"
            dest.mkdir(parents=True, exist_ok=True)
            shutil.copy(vm, dest / vm.name)
            c.vendor_master_path = str(dest / vm.name)
        per = Period(client_id=c.id, period=meta["return_period"], status="files_uploaded")
        db.add(per)
        db.flush()

        def add(src, role, hint=""):
            dest = FILES / str(c.id) / per.period / f"demo_{role}_{src.stem[:20].replace(' ', '_')}"
            dest.mkdir(parents=True, exist_ok=True)
            shutil.copy(src, dest / src.name)
            p = dest / src.name
            db.add(StoredFile(period_id=per.id, role=role, filename=src.name, path=str(p), size=p.stat().st_size,
                              sha256=S.sha256_file(p), period_hint=hint, uploaded_by="demo"))

        add(d / F["books_xlsx"], "books")
        for mon, name in F["portal_xlsx"].items():
            add(d / name, "portal", mon)
        db.commit()
        db.refresh(per)
        if reconcile_n is None or i < reconcile_n:
            S.run_period(db, per, user)
        made += 1
    return made
